@dash_plugin
def init_dash(dash_app):
    """Initialize the Plotly Dash application."""

    import dash.html as html
    import dash.dcc as dcc
    from dash import Input, Output, State, no_update
    from dash.exceptions import PreventUpdate
    import dash_bootstrap_components as dbc

    # Create a new page at the path `/dash/{plugin_name}`.
    @web_page('{plugin_name}', page_group='{plugin_name}', login_required=False)
    def page_layout():
        """Return the layout objects for this page."""
        return dbc.Container([
            dcc.Location(id='{plugin_name}-location'),
            html.Div(id='{plugin_name}-output-div'),
        ])

    @dash_app.callback(
        Output('{plugin_name}-output-div', 'children'),
        Input('{plugin_name}-location', 'pathname'),
    )
    def render_page_on_url_change(pathname: str):
        """Reload page contents when the URL path changes."""
        return html.H1("Hello from plugin '{plugin_name}'!")
